"""Stream implementations."""

import typing
from io import BytesIO

from jsilib import _utils
from jsilib._compat import asyncio

from . import exc as aio_exc
from .interface import IReadOnlyStream, IStream

__all__ = export = _utils.ExportList()


@export
class QueueReadOnlyStream(IReadOnlyStream):
    """A read-only stream that uses async queue as a source of data for
    reading.

    Whith this stream, :meth:`read` blocks when there is no data to be read
    from the queue. Useful for communicating callback-based code with
    awaitables.
    """
    _close_signal = object()

    def __init__(self, queue: asyncio.Queue[typing.Union[bytes, typing.Any]]):
        self._queue = queue
        self._buffer = b''
        self._closed = False

    def is_closed(self) -> bool:
        return self._closed

    async def close(self):
        self._closed = True
        self._queue.put_nowait(self._close_signal)

    async def read(self, count: int) -> bytes:
        if not self._buffer:
            received = await self._queue.get()
            if received is self._close_signal:
                raise aio_exc.StreamClosedError()
            self._buffer += received
        data = self._buffer[:count]
        self._buffer = self._buffer[count:]
        return data


@export
class QueueStream(IStream):
    """A stream that is reading/writing data from/to given async queues.

    With this stream, :meth:`read` blocks until there is data available in the
    *input* queue. On the other hand, :meth:`write` does not block, but
    instantly populates given *output* queue with written bytes.

    This can be used to create two streams that can talk to each other via
    queues.

    :param input:
        Input queue (for reading)

    :param output:
        Output queue (for writing)
    """

    def __init__(self, input: asyncio.Queue[bytes], output: asyncio.Queue[bytes]):
        self._input = QueueReadOnlyStream(input)
        self._output = output

    def is_closed(self) -> bool:
        return self._input.is_closed()

    async def close(self):
        return await self._input.close()

    async def read(self, count: int) -> bytes:
        return await self._input.read(count)

    async def write(self, data: bytes) -> int:
        if self._input.is_closed():
            raise aio_exc.StreamClosedError()
        self._output.put_nowait(data)
        return len(data)


@export
class ByteStream(IStream):
    """Acts similarly to :class:`io.BytesIO`, but implements :class:`IStream`
    async interface to do so."""

    def __init__(self, initial_bytes: bytes = None):
        self._storage = BytesIO(initial_bytes)

    @property
    def data(self) -> bytes:
        return self._storage.getvalue()

    def is_closed(self) -> bool:
        return self._storage.closed

    async def close(self):
        self._storage.close()

    async def read(self, count: int) -> bytes:
        if self._storage.closed:
            raise aio_exc.StreamClosedError()
        return self._storage.read(count)

    async def write(self, data: bytes) -> int:
        if self._storage.closed:
            raise aio_exc.StreamClosedError()
        return self._storage.write(data)
